}


class BundleConfig(BaseModel):
    """A validated resource bundle for placement.

    ``CPU`` and ``GPU`` default to ``0.0``. Any additional keyword arguments are
    treated as named resources (e.g. ``TPU=4.0``). All values are coerced to
    floats and must be non-negative numbers.
    """

    model_config = ConfigDict(extra="allow")

    CPU: float = 0.0
    GPU: float = 0.0

    @model_validator(mode="before")
    @classmethod
    def _validate_resources(cls, data: Any) -> Any:
        if not isinstance(data, dict):
            return data

        validated = {}
        for name, value in data.items():
            # ``bool`` is a subclass of ``int`` but is not a valid resource value.
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Resource '{name}' must be a number, got {value!r}."
                )
            value = float(value)
            if value < 0:
                raise ValueError(
                    f"Resource '{name}' must be non-negative, got {value}."
                )
            validated[name] = value
        return validated


class PlacementGroupConfig(BaseModel):
    """A validated placement group configuration.

    Exactly one of ``bundles`` (an explicit list of bundles) or
    ``bundle_per_worker`` (a single bundle replicated per worker) must be
    provided. ``strategy`` must be one of the valid Ray placement group
    strategies.
    """

    bundles: Optional[List[BundleConfig]] = None
    bundle_per_worker: Optional[BundleConfig] = None
    strategy: str

    @model_validator(mode="before")
    @classmethod
    def _validate_strategy(cls, data: Any) -> Any:
        if isinstance(data, dict):
            strategy = data.get("strategy")
            if strategy is not None and strategy not in VALID_PLACEMENT_GROUP_STRATEGIES:
                raise ValueError(
                    f"Invalid strategy '{strategy}'. Supported strategies are: "
                    f"{sorted(VALID_PLACEMENT_GROUP_STRATEGIES)}."
                )
        return data

    @model_validator(mode="after")
    def _validate_bundles(self) -> "PlacementGroupConfig":
